static int buffered_read_zero_len(struct de_bufferedreadctx *brctx, /* <=== buffered_read_zero_len */ 
	de_buffered_read_cbfn cbfn)
{
	const u8 dummybuf[1] = { 0 };
	int ret;

	brctx->offset = 0;
	brctx->eof_flag = 1;
	brctx->bytes_consumed = 0;
	ret = cbfn(brctx, dummybuf, 0);
	return ret?1:0;
}

void de_uchar_to_utf8(de_rune u1, u8 *utf8buf, i64 *p_utf8len) /* <=== de_uchar_to_utf8 */ 
{
	u32 u = (u32)u1;

	// TODO: Maybe there should be a flag to tell what to do with
	// our special codepoints (DE_CODEPOINT_BYTE00, ...).
	if(u1<0 || u1>0x10ffff)	{
		u=0xfffd;
	}

	if(u<=0x7f) {
		*p_utf8len = 1;
		utf8buf[0] = (u8)u;
	}
	else if(u>=0x80 && u<=0x7ff) {
		*p_utf8len = 2;
		utf8buf[0] = 0xc0 | (u8)(u>>6);
		utf8buf[1] = 0x80 | (u&0x3f);
	}
	else if(u>=0x800 && u<=0xffff) {
		*p_utf8len = 3;
		utf8buf[0] = 0xe0 | (u8)(u>>12);
		utf8buf[1] = 0x80 | ((u>>6)&0x3f);
		utf8buf[2] = 0x80 | (u&0x3f);
	}
	else {
		*p_utf8len = 4;
		utf8buf[0] = 0xf0 | (u8)(u>>18);
		utf8buf[1] = 0x80 | ((u>>12)&0x3f);
		utf8buf[2] = 0x80 | ((u>>6)&0x3f);
		utf8buf[3] = 0x80 | (u&0x3f);
	}
}

